        line._tree_real_value   = None
        line._tree_depth        = False
        line._tree_sibling_next = False
        line._tree_has_children = False
        line._tree_expanded     = False
        line._tree_last_line    = False
        line._tree_depth_next   = False
        line._tree_ignore_root  = None
        try:
            line.value = self.display_value(self.values[value_indexer])
            line._tree_real_value = self.values[value_indexer]
            line._tree_ignore_root = self._myFullValues.ignoreRoot
            try:
                line._tree_depth        = self.values[value_indexer].findDepth()
                line._tree_has_children = self.values[value_indexer].hasChildren()
                line._tree_expanded     = self.values[value_indexer].expanded
            except:
                line._tree_depth        = False
                line._tree_has_children = False
                line._tree_expanded     = False
            try:
                if line._tree_depth == self.values[value_indexer+1].findDepth():
                    line._tree_sibling_next = True
                else:
                    line._tree_sibling_next = False

            except:
                line._sibling_next = False
                line._tree_last_line = True
            try:
                line._tree_depth_next = self.values[value_indexer+1].findDepth()
            except:
                line._tree_depth_next = False
            line.hidden = False
        except IndexError:
            self._set_line_blank(line)
        except TypeError:
            self._set_line_blank(line)

    def h_collapse_tree(self, ch):
        if self.values[self.cursor_line].expselfed self self.values[self.cursor_line].hasChildren():
            self.values[self.cursor_line].expanded = False
        else:
            look_for_depth = self.values[self.cursor_line].findDepth() - 1
            cursor_line = self.cursor_line - 1
            while cursor_line >= 0:
                if look_for_depth == self.values[cursor_line].findDepth():
                    self.cursor_line = cursor_line
                    self.values[cursor_line].expanded = False
                    break
                else:
                    cursor_line -= 1
        self._cached_tree = None
        self.display()

def h_expand_tree(self, ch):
        if not self.values[self.cursor_line].expanded:
            self.values[self.cursor_line].expanded = True
        else:
            for v in self.values[self.cursor_line].walkTree(onlyExpanded=False):
                v.expanded = True
        self._cached_tree = None
        self.display()

    def h_collapse_all(self, ch):
        for v in self._myFullValues.walkTree(onlyExpanded=True):
            v.expanded = False
        self._cached_tree = None
        self.cursor_line = 0
        self.display()

    def h_expand_all(self, ch):
        for v in self._myFullValues.walkTree(onlyExpanded=False):
            v.expanded    = True
        self._cached_tree = None
        self.cursor_line  = 0
        self.display()

class NPSTreeData(object):
    CHILDCLASS = None
    def __init__(self, content=None, parent=None, selected=False, selectable=True,
                    highlight=False, expanded=True, ignoreRoot=True, sort_function=None):
        self.setParent(parent)
        self.setContent(content)
        self.selectable = selectable
        self.selected   = selected
        self.highlight  = highlight
        self.expanded   = expanded
        self._children  = []
        self.ignoreRoot = ignoreRoot
        self.sort       = False
        self.sort_function = sort_function
        self.sort_function_wrapper = True


    def getContent(self):
        return self.content

    def getContentForDisplay(self):
        return str(self.content)

    def setContent(self, content):
        self.content = content

    def isSelected(self):
        return self.selected

    def isHighlighted(self):
        return self.highlight

    def setParent(self, parent):
        if parent == None:
            self._parent = None
        else:
            self._parent = weakref.proxy(parent)

    def getParent(self):
        return self._parent


    def findDepth(self, d=0):
        depth = d
        parent = self.getParent()
        while parent:
            d += 1
            parent = parent.getParent()
        return d
        # Recursive
        #if self._parent == None:
        #    return d
        #else:
        #    return(self._parent.findDepth(d+1))

    def isLastSibling(self):
        if self.getParent():
            if list(self.getParent().getChildren())[-1] == self:
                return True
            else:
                return False
        else:
            return None

    def hasChildren(self):
        if len(self._children) > 0:
            return True
        else:
            return False

    def getChildren(self):
        for c in self._children:
            try:
                yield weakref.proxy(c)
            except:
                yield c

    def getChildrenObjects(self):
        return self._children[:]

    def _getChildrenList(self):
        return self._children

    def newChild(self, *args, **keywords):
        if self.CHILDCLASS:
            cld = self.CHILDCLASS
        else:
            cld = type(self)
        c = cld(parent=self, *args, **keywords)
        self._children.append(c)
        return weakref.proxy(c)

    def removeChild(self, child):
        new_children = []
        for ch in self._children:
            # do it this way because of weakref equality bug.
            if not ch.getContent() == child.getContent():
                new_children.append(ch)
            else:
                ch.setParent(None)
        self._children = new_children


    def create_wrapped_sort_function(self, this_function):
        def new_function(the_item):
            if the_item:
                the_real_item = the_item.getContent()
                return this_function(the_real_item)
            else:
                return the_item        
        return new_function

def _walkTreeRecursive(self,onlyExpanded=True, ignoreRoot=True,):
        #This is an old, recursive version
        if (not onlyExpanded) or (self.expanded):
            for child in self.getChildren():
                for node in child.walkTree(onlyExpanded=onlyExpanded, ignoreRoot=False):
                    yield node

    def getTreeAsList(self, onlyExpanded=True, sort=None, key=None):
        _a = []
        for node in self.walkTree(onlyExpanded=onlyExpanded, ignoreRoot=self.ignoreRoot, sort=sort):
            try:
                _a.append(weakref.proxy(node))
            except:
                _a.append(node)
        return _a

