def _type_based_yield(
    old_member: Object | Alias,
    new_member: Object | Alias,
    *,
    ignore_private: bool,
    seen_paths: set[str],
) -> Iterator[Breakage]:
    if old_member.path in seen_paths:
        return
    seen_paths.add(old_member.path)
    if old_member.is_alias or new_member.is_alias:
